def neighbour_counts(grid):
    rows = len(grid)
    cols = len(grid[0]) if grid else 0
    counts = [[0] * cols] * rows
    for r in range(rows):
        for c in range(cols):
            for nr in range(max(r - 1, 0), min(r + 2, rows)):
                for nc in range(max(c - 1, 0), min(c + 2, cols)):
                    if (nr, nc) != (r, c):
                        counts[r][c] += grid[nr][nc]
    return counts

